def age_on(born, day) -> int:
    """Age in whole years on `day`."""
    return day.year - born.year - ((day.month, day.day) < (born.month, born.day))


def add_discount(invoice: Invoice, name: str, percent: int) -> None:
    """A percentage off the consultation lines, as its own line right after the last of them (billing/AGENTS.md)."""
    consults = [i for i, line in enumerate(invoice.lines) if line.kind == "consult"]
    discount = percent_of(sum(invoice.lines[i].amount for i in consults), percent)
    if consults and discount:
        invoice.lines.insert(consults[-1] + 1, Line(f"{name} ({percent}%)", -discount, 1, "discount"))


